  "headline": "Vasopressin is not on FDA's shortage list as of 2026-10-21; Corvale East has 36.7 days on hand and Corvale General has 29.3 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include vasopressin as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 161 vials of the 1 mL injection at a use rate of 4.4 vials per day, providing 36.7 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 185 vials at a use rate of 6.3 vials per day, providing 29.3 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The rule‑based alternate manufacturer ranked first is Dr. Reddy's Laboratories, Inc., whose plant Dr. Reddy's Laboratories Limited-FTO-9 was last inspected on 2024-05-17 and classified VAI.",
      "cites": ["D4"]
    },
    {
      "text": "American Regent, Inc. is ranked next with a plant last inspected on 2026-06-18 and classified VAI.",
      "cites": ["D5"]
    },
    {
      "text": "Amneal Pharmaceuticals LLC is also ranked but its label names no plant that could be placed.",
      "cites": ["D6"]
    },
    {
      "text": "The current label in use names Medical Purchasing Solutions, LLC as the repackager, a registered plant last inspected on 2024-09-11 with a VAI classification.",
      "cites": ["E4", "E3"]
    }
  ]
}
